import re

from claude_md.checks._markdown import fenced_blocks, prose_lines
from claude_md.findings import Context, Finding, Source, check
from claude_md.model import LoadedFile, LoadMode

BEST_PRACTICES = Source("docs", "https://code.claude.com/docs/en/best-practices")
HEURISTIC = Source("heuristic", None)

LINTER_PATTERNS = [
    r"indent(ation)?\s*(size|with|using)?\s*\d",
    r"(tab|space)s?\s*(for|as)\s*indent",
    r"semicolon",
    r"trailing\s*(comma|whitespace|space)",
    r"single\s*quotes?\s*(vs|or|over)\s*double",
    r"double\s*quotes?\s*(vs|or|over)\s*single",
    r"max\s*line\s*length",
    r"prettier",
    r"eslint\s*(rule|config)",
]

VAGUE_PATTERNS = [
    r"(format|write|style)\s*(code|it)?\s*properly",
    r"follow\s*best\s*practices",
    r"keep\s*(code|it)\s*clean",
    r"write\s*good\s*(code|tests)",
    r"be\s*careful\s*with",
    r"try\s*to\s*(avoid|use|keep)",
]

MAX_CODE_BLOCK_LINES = 5
MIN_NARRATIVE_LINES = 3

_LOADED = frozenset({LoadMode.ALWAYS, LoadMode.CONDITIONAL})
_STRUCTURAL = re.compile(r"^\s*(#|[-*+]\s|\d+[.)]\s)")


def _loaded(files: list[LoadedFile]) -> list[LoadedFile]:
    return [f for f in files if f.mode in _LOADED]


@check("vague-instruction", BEST_PRACTICES, weight=3, cap=9)
def vague_instruction(files: list[LoadedFile], ctx: Context) -> list[Finding]:
    found: list[Finding] = []
    for file in _loaded(files):
        for number, line in prose_lines(file.text):
            lowered = line.lower()
            for pattern in VAGUE_PATTERNS:
                match = re.search(pattern, lowered)
                if match:
                    found.append(
                        Finding(
                            "vague-instruction",
                            "warning",
                            file.path,
                            number,
                            f"{file.path}:{number} has a vague instruction: "
                            f"'{match.group()}'.",
                            "Replace it with a specific, verifiable directive, "
                            "such as the exact command or convention to follow.",
                            BEST_PRACTICES,
                        )
                    )
    return found


@check("linter-rule", HEURISTIC, weight=2, cap=6)
def linter_rule(files: list[LoadedFile], ctx: Context) -> list[Finding]:
    found: list[Finding] = []
    for file in _loaded(files):
        hit = next(
            (
                (number, match.group())
                for number, line in prose_lines(file.text)
                for pattern in LINTER_PATTERNS
                if (match := re.search(pattern, line.lower()))
            ),
            None,
        )
        if hit:
            number, text = hit
            found.append(
                Finding(
                    "linter-rule",
                    "issue",
                    file.path,
                    number,
                    f"{file.path}:{number} states a formatting rule "
                    f"('{text}') that a linter or formatter normally enforces.",
                    "Move the rule into the formatter or linter config and "
                    "remove it from this file.",
                    HEURISTIC,
                )
            )
    return found


@check("narrative-paragraph", HEURISTIC, weight=1, cap=3)
def narrative_paragraph(files: list[LoadedFile], ctx: Context) -> list[Finding]:
    return [
        Finding(
            "narrative-paragraph",
            "suggestion",
            file.path,
            run[0],
            f"{file.path}:{run[0]} has a {len(run)}-line prose paragraph.",
            "Rewrite it as short bullet points, one instruction each.",
            HEURISTIC,
        )
        for file in _loaded(files)
        for run in _prose_runs(file.text)
        if len(run) >= MIN_NARRATIVE_LINES
    ]


def _prose_runs(text: str) -> list[list[int]]:
    runs: list[list[int]] = [[]]
    for number, line in prose_lines(text):
        if not line.strip() or _STRUCTURAL.match(line):
            runs.append([])
        elif runs[-1] and number != runs[-1][-1] + 1:
            runs.append([number])
        else:
            runs[-1].append(number)
    return runs


@check("code-block-long", HEURISTIC, weight=1, cap=3)
def code_block_long(files: list[LoadedFile], ctx: Context) -> list[Finding]:
    return [
        Finding(
            "code-block-long",
            "suggestion",
            file.path,
            block.start,
            f"{file.path}:{block.start} has a {block.length}-line code block "
            f"(over {MAX_CODE_BLOCK_LINES}).",
            "Point to the real file as file:line instead of pasting the code.",
            HEURISTIC,
        )
        for file in _loaded(files)
        for block in fenced_blocks(file.text)
        if block.length > MAX_CODE_BLOCK_LINES
    ]

from dataclasses import dataclass, field
from enum import StrEnum
from pathlib import Path

from claude_md.text import estimate_tokens


class Scope(StrEnum):
    MANAGED = "managed"
    USER = "user"
    USER_RULE = "user_rule"
    ANCESTOR = "ancestor"
    PROJECT = "project"
    LOCAL = "local"
    PROJECT_RULE = "project_rule"
    NESTED = "nested"
    IMPORT = "import"
    MEMORY = "memory"
    AGENTS = "agents"


class LoadMode(StrEnum):
    ALWAYS = "always"
    CONDITIONAL = "conditional"
    ON_DEMAND = "on_demand"
    EXCLUDED = "excluded"
    DORMANT = "dormant"
    SKIPPED = "skipped"


@dataclass
class LoadedFile:
    path: Path
    scope: Scope
    mode: LoadMode
    order: int
    raw: str
    text: str
    paths: list[str] | None = None
    imported_by: Path | None = None
    external: bool = False
    notes: list[str] = field(default_factory=list)

    @property
    def lines(self) -> int:
        return len(self.text.splitlines())

    @property
    def bytes(self) -> int:
        return len(self.text.encode("utf-8"))

    @property
    def tokens(self) -> int:
        return estimate_tokens(self.text)


@dataclass
class Totals:
    always: int = 0
    conditional: int = 0
    on_demand: int = 0


def totals(files: list[LoadedFile]) -> Totals:
    result = Totals()
    for file in files:
        if file.mode == LoadMode.ALWAYS:
            result.always += file.tokens
        elif file.mode == LoadMode.CONDITIONAL:
            result.conditional += file.tokens
        elif file.mode == LoadMode.ON_DEMAND:
            result.on_demand += file.tokens
    return result

